#!/usr/bin/env python3
"""Emit an independently written functional pitch-command model; no firmware.

The formula is one reconstruction inside all 383 ordinary rounding intervals,
with the observed index257 exception. It is not Yamaha's generation algorithm.
--check validates generated bytes against independently audited table hashes.
Optional --rom-dir compares these functional values with the three local ROMs;
neither ROM bytes nor disassembly are emitted or required to build the product.
"""
from pathlib import Path
import argparse
import hashlib
import json
import math
import struct

ROOT = Path(__file__).resolve().parents[1]
HEADER = ROOT / "Source/DSP/FirmwarePitch.h"
PITCH_SHA = "44463488472438e85333630f9149e08b34baff846dd305398ed0273204cc8bdc"
BEND_SHA = "5b6a19b2d2cb8b613ed2b1f015c67fe98b97299c26bb2e3caf2fc63089de33dc"
ROMS = {
    "xe418c0-077.ic4": "c0015cbb34f50ac5687db9def679117e4b2bad32",
    "xe416d0-093.ic4": "d578324cfae73cd5f6c628eb3044be07684bc5d0",
    "xg503b0-132.ic4": "33cc3f4ab27cf6e5068627625f6ab236209ad776",
}


def words():
    return [3838 if i == 257 else math.floor(2394.41 * 2 ** (i / 384) + .5)
            for i in range(384)]


def bend(high, span):
    high = {62: 61, 127: 128}.get(high, high)
    return math.trunc(span * (high - 64) / 2)


def generated():
    rows = ["    " + ", ".join(str(v) for v in words()[i:i+12]) + ","
            for i in range(0, 384, 12)]
    return '''// Generated by Tools/generate_firmware_pitch.py; do not hand edit.
#pragma once
#include <array>
#include <cmath>
#include <cstdint>

namespace press78::firmware_pitch {
// Independently reconstructed command values, verified against three sibling
// firmwares. No original executable code is included. The exceptional word257
// is intentional. Formula scale2394.41 is nonunique, not a recovered algorithm.
inline constexpr std::array<std::uint16_t, 384> words{{
''' + "\n".join(rows) + '''
}};
inline constexpr const char* tableSha256 = "''' + PITCH_SHA + '''";
inline constexpr const char* bendTableSha256 = "''' + BEND_SHA + '''";

// Verified positive hardware spans1..12. Zero and13..24 are explicit plugin
// extensions. MIDI's low seven bend bits have no effect on this software path.
inline constexpr int bendSteps(int high, int span) noexcept {
    const int j = high == 62 ? 61 : high == 127 ? 128 : high;
    return span * (j - 64) / 2; // C++ signed division truncates toward zero.
}
struct PitchWord { int word, block; };
inline constexpr PitchWord extendedWord(int coordinate) noexcept {
    // Signed coordinate is measured in1/32 semitones. Extrapolation preserves
    // the plugin's extended keyboard/bend range; it does not impose TrueVoice's
    // high-note clamp. Negative coordinates require floor, not truncation.
    const int octave = coordinate >= 0 ? coordinate / 384 : (coordinate - 383) / 384;
    return {words[static_cast<unsigned>(coordinate - octave * 384)], octave - 1};
}
inline double frequency(int note, int steps = 0) noexcept {
    const auto p = extendedWord(note * 32 + steps);
    // Behavioral downstream hypothesis: command words/block are verified;
    // this floor, reference clock, and internal phase/cadence are not silicon
    // measurements. Very low extended notes may quantize to zero.
    const double grid = std::floor(std::ldexp(static_cast<double>(p.word), p.block - 3));
    return grid * (5500000.0 / (6.0 * 16777216.0));
}
struct Write { int address, value; };
inline constexpr std::array<Write, 3> commands(int note, int fraction, int voice = 0) noexcept {
    // Exact documented research fixture for the firmware converter boundary;
    // the audible engine deliberately uses extendedWord instead of this cap.
    note &= 127; fraction &= 31;
    int block = note / 12 - 1;
    const int index = 32 * (note % 12) + fraction;
    int word = 0;
    if (block >= 9 || (block == 8 && index >= 288)) { block = 7; word = 8054; }
    else {
        word = words[static_cast<unsigned>(index)];
        if (block == -1) { word /= 2; block = 0; }
        while (block >= 8) { word *= 2; --block; }
    }
    const int mark = (voice & 1) * 128, pair = voice / 2;
    return {{{0x228 + pair, mark | ((word >> 6) & 31)},
             {0x230 + pair, mark | (word & 63)},
             {0x238 + pair, mark | ((word >> 6) & 96) | (block << 2)}}};
}
} // namespace press78::firmware_pitch
'''


def main():
    p = argparse.ArgumentParser(description=__doc__)
    p.add_argument("--check", action="store_true")
    p.add_argument("--rom-dir", type=Path)
    args = p.parse_args()
    pitch = struct.pack("<384H", *words())
    bends = struct.pack("<1536h", *(bend(h, s) for s in range(1, 13) for h in range(128)))
    assert hashlib.sha256(pitch).hexdigest() == PITCH_SHA
    assert hashlib.sha256(bends).hexdigest() == BEND_SHA
    checked = []
    if args.rom_dir:
        for name, sha in ROMS.items():
            data = (args.rom_dir / name).read_bytes()
            assert hashlib.sha1(data).hexdigest() == sha, name
            assert data[0x9d7b:0xa07b] == pitch, name
            assert data[0x9179:0x9d79] == bends, name
            checked.append(name)
    text = generated()
    if args.check:
        if not HEADER.exists() or HEADER.read_text() != text:
            raise SystemExit("FirmwarePitch.h is stale; run Tools/generate_firmware_pitch.py")
    else:
        HEADER.write_text(text)
    print(json.dumps({"pitch_words":384,"bend_words":1536,"pitch_sha256":PITCH_SHA,
                      "bend_sha256":BEND_SHA,"local_roms_checked":checked,"passed":True}))


if __name__ == "__main__":
    main()
